async function generarPassword(){try{const response=await fetch("?handler=GenerarPassword"),data=await response.json(),nuevaPasswordInput=document.getElementById("Modelo_NuevaPassword"),confirmarPasswordInput=document.getElementById("Modelo_ConfirmarPassword");nuevaPasswordInput&&(nuevaPasswordInput.value=data.password);confirmarPasswordInput&&(confirmarPasswordInput.value=data.password)}catch(error){console.error("Error al generar contraseña:",error);alert("Error al generar la contraseña. Por favor, inténtalo manualmente.")}}document.addEventListener("DOMContentLoaded",function(){const btnGenerarPassword=document.querySelector("[data-js-generar-password]");btnGenerarPassword&&btnGenerarPassword.addEventListener("click",generarPassword)});